<form method="get" class="card search-form" role="search"><h2><?= $e($t('Find a story')) ?></h2><div class="two"><label><?= $e($t('Search title, passport code or steward')) ?><input type="search" name="q" maxlength="200" value="<?= $e($filters['q']??'') ?>"></label><label><?= $e($t('Media type')) ?><select name="media"><option value=""><?= $e($t('All types')) ?></option><?php foreach (['text','image','audio','video'] as $value): ?><option value="<?= $e($value) ?>" <?= ($filters['media']??'')===$value?'selected':'' ?>><?= $e($t(ucfirst($value))) ?></option><?php endforeach ?></select></label><label><?= $e($t('Language')) ?><input name="language" maxlength="100" value="<?= $e($filters['language']??'') ?>"></label><label><?= $e($t('Community collection')) ?><input name="community" maxlength="200" value="<?= $e($filters['community']??'') ?>"></label><label><?= $e($t('Declared review status')) ?><select name="status"><option value=""><?= $e($t('All statuses')) ?></option><?php foreach (\Passport\Copy::STATUS as $value=>$label): ?><option value="<?= $e($value) ?>" <?= ($filters['status']??'')===$value?'selected':'' ?>><?= $e($label) ?></option><?php endforeach ?></select></label></div><div class="actions"><button class="button"><?= $e($t('Search stories')) ?></button><a href="<?= $e($view==='dashboard'?'/dashboard':'/#passports') ?>"><?= $e($t('Clear filters')) ?></a></div><p class="muted"><?= $e($t('Public searches use visible fields only. Hidden stories do not appear in media, language or collection filters.')) ?></p></form>
